const payload = $input.first().json.body || $input.first().json || {};
const eventType = payload.event_type || 'SYSTEM_EVENT';
let severity = payload.severity || 'INFO';
if (eventType === 'LOW_MATERIAL_STOCK' || Number(payload.total_amount || 0) >= 20000000) {
  severity = 'CRITICAL';
} else if (eventType === 'NEW_SALES_ORDER' || eventType === 'REQUISITION_APPROVED') {
  severity = 'WARNING';
}
return [{
  json: {
    title: payload.title || `[n8n Auto] ${eventType}`,
    message: payload.message || 'Sự kiện nghiệp vụ được xử lý tự động bởi n8n Workflow.',
    severity,
    event_type: eventType,
    processed_at: new Date().toISOString()
  }
}];
